/*
 * fastapi-webrtc browser runtime for signaling protocol "fastapi-webrtc.v1".
 *
 * Generated by fastapi-webrtc; do not edit. Regenerate the client instead.
 * The runtime is framework-free: it only uses WebSocket, RTCPeerConnection and
 * the other standard browser WebRTC APIs.
 */

export const SUBPROTOCOL = "fastapi-webrtc.v1";
export const PROTOCOL_VERSION = 1;

/** Error categories shared with the server, plus client-only categories. */
export type ErrorCode =
  | "closed"
  | "shutdown"
  | "protocol_error"
  | "unsupported_protocol"
  | "session_limit"
  | "negotiation_failed"
  | "negotiation_timeout"
  | "media_timeout"
  | "media_rejected"
  | "transport_lost"
  | "signaling_lost"
  | "engine_failure"
  | "handler_failure"
  | "queue_exhausted"
  | "slow_consumer"
  | "message_too_large"
  | "invalid_message"
  | "channel_rejected"
  | "channel_closed"
  /** The WebSocket could not be opened: network failure or HTTP admission denial. */
  | "connection_failed"
  /** The caller aborted the connection with an AbortSignal. */
  | "aborted";

const ERROR_CODES: ReadonlySet<string> = new Set<ErrorCode>([
  "closed",
  "shutdown",
  "protocol_error",
  "unsupported_protocol",
  "session_limit",
  "negotiation_failed",
  "negotiation_timeout",
  "media_timeout",
  "media_rejected",
  "transport_lost",
  "signaling_lost",
  "engine_failure",
  "handler_failure",
  "queue_exhausted",
  "slow_consumer",
  "message_too_large",
  "invalid_message",
  "channel_rejected",
  "channel_closed",
  "connection_failed",
  "aborted",
]);

export class RtcError extends Error {
  readonly code: ErrorCode;
  readonly channel: string | undefined;
  /** WebSocket close code, when the error ended the session. */
  readonly closeCode: number | undefined;

  constructor(
    code: ErrorCode,
    message?: string,
    options: { channel?: string | undefined; closeCode?: number | undefined; cause?: unknown } = {},
  ) {
    super(message ?? code, options.cause === undefined ? undefined : { cause: options.cause });
    this.name = "RtcError";
    this.code = code;
    this.channel = options.channel;
    this.closeCode = options.closeCode;
  }
}

export function isRtcError(value: unknown): value is RtcError {
  return value instanceof RtcError;
}

/** Media direction from the server's point of view. */
export type Direction = "send" | "receive" | "send_receive";
export type MessageFormat = "raw" | "text" | "binary" | "json";
export type Role = "answerer" | "offerer";

export interface ParameterDescriptor {
  readonly name: string;
  readonly key: string;
  readonly in: "path" | "query";
  readonly required: boolean;
}

export interface ChannelDescriptor {
  readonly name: string;
  /** Format the server accepts, which the client sends. */
  readonly receiveFormat: MessageFormat;
  /** Format the server sends, which the client receives. */
  readonly sendFormat: MessageFormat;
}

export interface SessionDescriptor {
  readonly name: string;
  readonly path: string;
  readonly role: Role;
  readonly media: { readonly audio: Direction | null; readonly video: Direction | null };
  readonly channels: readonly ChannelDescriptor[];
  readonly parameters: readonly ParameterDescriptor[];
}

export type QueryValue =
  | string
  | number
  | boolean
  | null
  | undefined
  | readonly (string | number | boolean)[];
export type QueryParams = Readonly<Record<string, QueryValue>>;

export type WebSocketFactory = new (url: string, protocols?: string | string[]) => WebSocket;
export type PeerConnectionFactory = new (configuration?: RTCConfiguration) => RTCPeerConnection;

export interface ClientConfig {
  /** HTTP(S) or WS(S) origin and optional path prefix. Defaults to `location.origin`. */
  readonly baseUrl?: string | URL;
  /**
   * Extra query parameters for every session, for example an access token.
   * Browsers cannot set headers on WebSockets; cookies are sent automatically.
   */
  readonly query?: QueryParams | (() => QueryParams | Promise<QueryParams>);
  /** Merged into every peer connection's configuration. */
  readonly rtcConfiguration?: RTCConfiguration;
  readonly WebSocket?: WebSocketFactory;
  readonly RTCPeerConnection?: PeerConnectionFactory;
}

/** Message types of one channel, from the client's point of view. */
export interface ChannelTypes {
  readonly send: unknown;
  readonly receive: unknown;
}
export type ChannelMap = { readonly [name: string]: ChannelTypes };

export type SessionState = "connecting" | "open" | "closed";

export interface RemoteTrack {
  readonly track: MediaStreamTrack;
  readonly streams: readonly MediaStream[];
  readonly receiver: RTCRtpReceiver;
  readonly transceiver: RTCRtpTransceiver;
}

export type MessageHandlers<C extends ChannelMap> = {
  readonly [K in keyof C]?: (message: C[K]["receive"], session: RtcSession<C>) => void | Promise<void>;
};

export interface ConnectOptions<C extends ChannelMap> {
  /**
   * Local tracks to send. They stay owned by the caller: the session never
   * stops them, also not when it closes.
   */
  readonly tracks?: readonly MediaStreamTrack[] | MediaStream;
  readonly signal?: AbortSignal;
  /** Deadline for the whole connection, in milliseconds. Defaults to 30 s. */
  readonly timeoutMs?: number;
  readonly query?: QueryParams;
  readonly rtcConfiguration?: RTCConfiguration;
  /** Send buffer size above which `send()` waits. Defaults to 1 MiB. */
  readonly sendBufferHighBytes?: number;
  readonly onTrack?: (track: RemoteTrack, session: RtcSession<C>) => void;
  readonly onMessage?: MessageHandlers<C>;
  readonly onStateChange?: (state: SessionState, session: RtcSession<C>) => void;
  /** Non-terminal errors, for example a rejected message. */
  readonly onError?: (error: RtcError, session: RtcSession<C>) => void;
  /** Called once when the session ended, also after a failed connect. */
  readonly onClose?: (reason: RtcError) => void;
}

export interface RtcChannel<TSend, TReceive> {
  readonly name: string;
  readonly isOpen: boolean;
  readonly bufferedAmount: number;
  readonly dataChannel: RTCDataChannel;
  /**
   * Encode, size-check and send a message. Waits while the channel is not yet
   * open or its send buffer is above the high-water mark.
   */
  send(message: TSend): Promise<void>;
  /** Receive messages; returns an unsubscribe function. */
  subscribe(handler: (message: TReceive) => void | Promise<void>): () => void;
}

export type SessionChannels<C extends ChannelMap> = {
  readonly [K in keyof C]: RtcChannel<C[K]["send"], C[K]["receive"]>;
};

export interface RtcSession<C extends ChannelMap> {
  readonly id: string;
  readonly name: string;
  readonly state: SessionState;
  readonly channels: SessionChannels<C>;
  readonly peerConnection: RTCPeerConnection;
  readonly remoteTracks: readonly RemoteTrack[];
  /** Resolves with the termination reason; `code` is `"closed"` for normal ends. */
  readonly closed: Promise<RtcError>;
  /** Send another borrowed track and wait for the renegotiation. */
  addTrack(track: MediaStreamTrack, ...streams: MediaStream[]): Promise<void>;
  /** Stop sending a track without stopping it, and wait for the renegotiation. */
  removeTrack(track: MediaStreamTrack): Promise<void>;
  stats(): Promise<RTCStatsReport>;
  /** Close the session. Idempotent; never stops borrowed local tracks. */
  close(): Promise<void>;
}

export interface SessionApi<C extends ChannelMap, O> {
  readonly descriptor: SessionDescriptor;
  connect(options: O): Promise<RtcSession<C>>;
}

export function sessionApi<C extends ChannelMap, O extends ConnectOptions<C>>(
  config: ClientConfig,
  descriptor: SessionDescriptor,
): SessionApi<C, O> {
  return {
    descriptor,
    connect: (options: O) => connectSession<C>(config, descriptor, options),
  };
}

// --------------------------------------------------------------- protocol

interface IceServerMessage {
  urls: string[];
  username?: string | null;
  credential?: string | null;
}

interface HelloChannel {
  name: string;
  id: number | null;
  negotiated: boolean;
  ordered: boolean;
  max_retransmits: number | null;
  max_packet_life_time_ms: number | null;
  max_message_bytes: number;
  receive_format: MessageFormat;
  send_format: MessageFormat;
}

interface HelloMessage {
  type: "session";
  protocol: number;
  session_id: string;
  name: string;
  role: Role;
  ice_servers: IceServerMessage[];
  media: { audio: Direction | null; video: Direction | null; max_incoming_tracks: number };
  channels: HelloChannel[];
  limits: { negotiation_timeout_ms: number; max_signaling_message_bytes: number };
  capabilities: { trickle_ice: boolean; ice_restart: boolean; renegotiation: boolean };
}

interface DescriptionMessage {
  type: "description";
  description: { type: "offer" | "answer"; sdp: string };
  negotiation: number;
}

interface CandidateMessage {
  type: "candidate";
  candidate: RTCIceCandidateInit | null;
}

interface ErrorMessage {
  type: "error";
  code: string;
  message: string;
  channel?: string | null;
}

type ServerMessage =
  | HelloMessage
  | { type: "ready" }
  | DescriptionMessage
  | CandidateMessage
  | ErrorMessage;

const DEFAULT_TIMEOUT_MS = 30_000;
const DEFAULT_SEND_BUFFER_HIGH_BYTES = 1024 * 1024;
const RESERVED_KEYS = new Set([
  "tracks",
  "signal",
  "timeoutMs",
  "query",
  "rtcConfiguration",
  "sendBufferHighBytes",
  "onTrack",
  "onMessage",
  "onStateChange",
  "onError",
  "onClose",
]);

/** Map a WebSocket close event to an error category. */
export function closeReason(code: number, reason: string, opened: boolean): RtcError {
  if (ERROR_CODES.has(reason)) {
    return new RtcError(reason as ErrorCode, undefined, { closeCode: code });
  }
  let category: ErrorCode;
  if (!opened) category = "connection_failed";
  else if (code === 1000) category = "closed";
  else if (code === 1001 || code === 1012) category = "shutdown";
  else if (code === 1008) category = "protocol_error";
  else if (code === 1009) category = "message_too_large";
  else if (code === 1011) category = "engine_failure";
  else if (code === 1013) category = "session_limit";
  else category = "signaling_lost";
  return new RtcError(category, reason || undefined, { closeCode: code });
}

/** Build the `ws:`/`wss:` URL of a session. */
export function sessionUrl(
  baseUrl: string | URL | undefined,
  descriptor: Pick<SessionDescriptor, "path" | "parameters">,
  values: Readonly<Record<string, unknown>>,
  ...queries: (QueryParams | undefined)[]
): string {
  const origin = baseUrl ?? (globalThis as { location?: { origin?: string } }).location?.origin;
  if (origin === undefined) {
    throw new TypeError("baseUrl is required outside of a browser page");
  }
  const url = new URL(String(origin));
  if (url.protocol === "http:") url.protocol = "ws:";
  else if (url.protocol === "https:") url.protocol = "wss:";
  else if (url.protocol !== "ws:" && url.protocol !== "wss:") {
    throw new TypeError(`Unsupported baseUrl protocol ${url.protocol}`);
  }
  const byName = new Map(descriptor.parameters.map((p) => [p.name, p] as const));
  const path = descriptor.path.replace(/\{([^}:]+)(?::([^}]+))?\}/g, (_match, name: string, converter?: string) => {
    const parameter = byName.get(name);
    const value = parameter === undefined ? undefined : values[parameter.key];
    if (value === undefined || value === null) {
      throw new TypeError(`Missing path parameter ${parameter?.key ?? name}`);
    }
    const text = String(value);
    return converter === "path"
      ? text.split("/").map(encodeURIComponent).join("/")
      : encodeURIComponent(text);
  });
  url.pathname = url.pathname.replace(/\/+$/, "") + path;
  for (const parameter of descriptor.parameters) {
    if (parameter.in !== "query") continue;
    const value = values[parameter.key];
    if (value === undefined && parameter.required) {
      throw new TypeError(`Missing query parameter ${parameter.key}`);
    }
    appendQuery(url, parameter.name, value as QueryValue);
  }
  for (const query of queries) {
    if (query === undefined) continue;
    for (const [name, value] of Object.entries(query)) {
      url.searchParams.delete(name);
      appendQuery(url, name, value);
    }
  }
  return url.toString();
}

function appendQuery(url: URL, name: string, value: QueryValue): void {
  if (value === undefined || value === null) return;
  const items = Array.isArray(value) ? value : [value];
  for (const item of items as readonly (string | number | boolean)[]) {
    url.searchParams.append(name, String(item));
  }
}

/** Encode a message the client sends, in the server's receive format. */
export function encodeMessage(
  format: MessageFormat,
  message: unknown,
): string | ArrayBuffer | ArrayBufferView {
  switch (format) {
    case "json": {
      const text = JSON.stringify(message);
      if (text === undefined) throw new RtcError("invalid_message", "The message is not JSON-serializable.");
      return text;
    }
    case "text":
      if (typeof message !== "string") throw new RtcError("invalid_message", "Text channels send strings.");
      return message;
    case "binary":
      if (message instanceof ArrayBuffer || ArrayBuffer.isView(message)) return message;
      throw new RtcError("invalid_message", "Binary channels send ArrayBuffer or typed array values.");
    case "raw":
      if (typeof message === "string" || message instanceof ArrayBuffer || ArrayBuffer.isView(message)) {
        return message;
      }
      throw new RtcError("invalid_message", "Raw channels send strings or binary values.");
  }
}

/** Decode a message the server sent, in the server's send format. */
export function decodeMessage(format: MessageFormat, data: unknown): unknown {
  switch (format) {
    case "json":
      if (typeof data !== "string") throw new RtcError("invalid_message", "Expected a JSON text message.");
      try {
        return JSON.parse(data);
      } catch (cause) {
        throw new RtcError("invalid_message", "Invalid JSON message.", { cause });
      }
    case "text":
      if (typeof data !== "string") throw new RtcError("invalid_message", "Expected a text message.");
      return data;
    case "binary":
      if (!(data instanceof ArrayBuffer)) throw new RtcError("invalid_message", "Expected a binary message.");
      return data;
    case "raw":
      return data;
  }
}

export function byteLength(data: string | ArrayBuffer | ArrayBufferView): number {
  if (typeof data === "string") return new TextEncoder().encode(data).byteLength;
  return data.byteLength;
}

function serverReceives(direction: Direction | null): boolean {
  return direction === "receive" || direction === "send_receive";
}

function serverSends(direction: Direction | null): boolean {
  return direction === "send" || direction === "send_receive";
}

function trackList(tracks: ConnectOptions<ChannelMap>["tracks"]): {
  tracks: readonly MediaStreamTrack[];
  streams: MediaStream[];
} {
  if (tracks === undefined) return { tracks: [], streams: [] };
  if (Array.isArray(tracks)) return { tracks, streams: [] };
  const stream = tracks as MediaStream;
  return { tracks: stream.getTracks(), streams: [stream] };
}

function checkTrack(media: SessionDescriptor["media"], track: MediaStreamTrack): void {
  const kind = track.kind === "audio" || track.kind === "video" ? track.kind : null;
  if (kind === null || !serverReceives(media[kind])) {
    throw new RtcError("media_rejected", `The session does not receive ${track.kind} tracks.`);
  }
}

// ----------------------------------------------------------------- session

export async function connectSession<C extends ChannelMap>(
  config: ClientConfig,
  descriptor: SessionDescriptor,
  options: ConnectOptions<C>,
): Promise<RtcSession<C>> {
  const local = trackList(options.tracks);
  for (const track of local.tracks) checkTrack(descriptor.media, track);
  if (options.signal?.aborted) {
    throw new RtcError("aborted", "The connection was aborted.", { cause: options.signal.reason });
  }
  const values: Record<string, unknown> = {};
  // Every option that the runtime does not consume is a session parameter.
  for (const [key, value] of Object.entries(options as object)) {
    if (!RESERVED_KEYS.has(key)) values[key] = value;
  }
  const shared = typeof config.query === "function" ? await config.query() : config.query;
  const url = sessionUrl(config.baseUrl, descriptor, values, shared, options.query);
  const connection = new Connection<C>(config, descriptor, options, local);
  return connection.start(url);
}

type Channel = {
  readonly name: string;
  readonly info: HelloChannel;
  data: RTCDataChannel | null;
  readonly handlers: Set<(message: unknown) => void | Promise<void>>;
  readonly waiters: Set<() => void>;
};

class Connection<C extends ChannelMap> {
  private readonly ws: WebSocketFactory;
  private readonly peerFactory: PeerConnectionFactory;
  private socket: WebSocket | null = null;
  private pc: RTCPeerConnection | null = null;
  private hello: HelloMessage | null = null;
  private helloReceived = false;
  private state: SessionState = "connecting";
  private opened = false;
  private ready = false;
  private finished: RtcError | null = null;
  private resolveConnect: ((session: RtcSession<C>) => void) | null = null;
  private rejectConnect: ((error: RtcError) => void) | null = null;
  private resolveClosed!: (reason: RtcError) => void;
  private readonly closedPromise: Promise<RtcError>;
  private readonly channels = new Map<string, Channel>();
  private readonly remoteTracks: RemoteTrack[] = [];
  private operations: Promise<void> = Promise.resolve();
  private pendingCandidates: (RTCIceCandidateInit | null)[] = [];
  private negotiationCounter = 0;
  private localOffer: number | null = null;
  private wantOffer = false;
  private settledWaiters: (() => void)[] = [];
  private initialTracksAttached = false;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private abortListener: (() => void) | null = null;
  private readonly session: RtcSession<C>;

  constructor(
    private readonly config: ClientConfig,
    private readonly descriptor: SessionDescriptor,
    private readonly options: ConnectOptions<C>,
    private readonly local: { tracks: readonly MediaStreamTrack[]; streams: MediaStream[] },
  ) {
    const ws = config.WebSocket ?? (globalThis as { WebSocket?: WebSocketFactory }).WebSocket;
    const peer =
      config.RTCPeerConnection ??
      (globalThis as { RTCPeerConnection?: PeerConnectionFactory }).RTCPeerConnection;
    if (ws === undefined || peer === undefined) {
      throw new TypeError("WebSocket and RTCPeerConnection are required");
    }
    this.ws = ws;
    this.peerFactory = peer;
    this.closedPromise = new Promise((resolve) => {
      this.resolveClosed = resolve;
    });
    this.session = this.createSession();
  }

  start(url: string): Promise<RtcSession<C>> {
    const promise = new Promise<RtcSession<C>>((resolve, reject) => {
      this.resolveConnect = resolve;
      this.rejectConnect = reject;
    });
    const signal = this.options.signal;
    if (signal !== undefined) {
      this.abortListener = () => {
        if (this.ready) void this.session.close();
        else this.finish(new RtcError("aborted", "The connection was aborted.", { cause: signal.reason }));
      };
      signal.addEventListener("abort", this.abortListener, { once: true });
    }
    this.timer = setTimeout(() => {
      this.finish(new RtcError("negotiation_timeout", "The session did not connect in time."));
    }, this.options.timeoutMs ?? DEFAULT_TIMEOUT_MS);
    try {
      const socket = new this.ws(url, [SUBPROTOCOL]);
      this.socket = socket;
      socket.binaryType = "arraybuffer";
      socket.onopen = () => {
        this.opened = true;
        if (socket.protocol !== "" && socket.protocol !== SUBPROTOCOL) {
          this.finish(new RtcError("unsupported_protocol"));
        }
      };
      socket.onmessage = (event: MessageEvent) => this.onSocketMessage(event.data);
      socket.onclose = (event: CloseEvent) => this.finish(closeReason(event.code, event.reason, this.opened));
      socket.onerror = () => undefined;
    } catch (cause) {
      this.finish(new RtcError("connection_failed", "The WebSocket could not be opened.", { cause }));
    }
    return promise;
  }

  // ------------------------------------------------------------- signaling

  private onSocketMessage(data: unknown): void {
    if (this.finished !== null) return;
    if (typeof data !== "string") {
      this.fail(new RtcError("protocol_error", "Unexpected binary signaling message."));
      return;
    }
    let message: ServerMessage;
    try {
      message = JSON.parse(data) as ServerMessage;
    } catch (cause) {
      this.fail(new RtcError("protocol_error", "Invalid signaling message.", { cause }));
      return;
    }
    // The hello is applied asynchronously; later messages queue behind it.
    if (!this.helloReceived) {
      if (message.type !== "session") {
        this.fail(new RtcError("protocol_error", "Expected the session message first."));
        return;
      }
      this.helloReceived = true;
      this.enqueue(() => this.onHello(message as HelloMessage));
      return;
    }
    switch (message.type) {
      case "description":
        this.enqueue(() => this.onDescription(message as DescriptionMessage));
        break;
      case "candidate":
        this.enqueue(() => this.onCandidate((message as CandidateMessage).candidate));
        break;
      case "ready":
        this.ready = true;
        this.checkOpen();
        break;
      case "error": {
        const error = message as ErrorMessage;
        const code = ERROR_CODES.has(error.code) ? (error.code as ErrorCode) : "protocol_error";
        this.report(new RtcError(code, error.message, { channel: error.channel ?? undefined }));
        break;
      }
      default:
        this.fail(new RtcError("protocol_error", "Unknown signaling message."));
    }
  }

  private enqueue(operation: () => Promise<void> | void): void {
    this.operations = this.operations
      .then(async () => {
        if (this.finished === null) await operation();
      })
      .catch((cause: unknown) => {
        this.fail(isRtcError(cause) ? cause : new RtcError("negotiation_failed", undefined, { cause }));
      });
  }

  private send(message: object): void {
    const socket = this.socket;
    if (socket !== null && socket.readyState === 1) socket.send(JSON.stringify(message));
  }

  private async onHello(hello: HelloMessage): Promise<void> {
    if (hello.protocol !== PROTOCOL_VERSION) {
      throw new RtcError("unsupported_protocol", `Server speaks protocol ${hello.protocol}.`);
    }
    const expected = this.descriptor.channels.map((c) => c.name).sort().join(",");
    const actual = hello.channels.map((c) => c.name).sort().join(",");
    if (hello.name !== this.descriptor.name || expected !== actual) {
      throw new RtcError("protocol_error", "The generated client does not match the server; regenerate it.");
    }
    this.hello = hello;
    const configuration: RTCConfiguration = {
      ...this.config.rtcConfiguration,
      ...this.options.rtcConfiguration,
    };
    if (configuration.iceServers === undefined) {
      configuration.iceServers = hello.ice_servers.map((server) => {
        const item: RTCIceServer = { urls: server.urls };
        if (server.username != null) item.username = server.username;
        if (server.credential != null) item.credential = server.credential;
        return item;
      });
    }
    const pc = new this.peerFactory(configuration);
    this.pc = pc;
    pc.onicecandidate = (event: RTCPeerConnectionIceEvent) => {
      this.send({ type: "candidate", candidate: event.candidate === null ? null : event.candidate.toJSON() });
    };
    pc.ontrack = (event: RTCTrackEvent) => {
      const track: RemoteTrack = {
        track: event.track,
        streams: event.streams,
        receiver: event.receiver,
        transceiver: event.transceiver,
      };
      this.remoteTracks.push(track);
      this.call(() => this.options.onTrack?.(track, this.session));
    };
    pc.ondatachannel = (event: RTCDataChannelEvent) => {
      const channel = this.channels.get(event.channel.label);
      if (channel === undefined || channel.data !== null) {
        event.channel.close();
        return;
      }
      this.bindChannel(channel, event.channel);
    };
    const offerer = hello.role === "answerer";
    for (const info of hello.channels) {
      const channel: Channel = { name: info.name, info, data: null, handlers: new Set(), waiters: new Set() };
      const handler = (this.options.onMessage as Record<string, ((m: unknown, s: RtcSession<C>) => void | Promise<void>) | undefined> | undefined)?.[info.name];
      if (handler !== undefined) channel.handlers.add((message) => handler(message, this.session));
      this.channels.set(info.name, channel);
      if (info.negotiated || offerer) {
        const init: RTCDataChannelInit = { ordered: info.ordered };
        if (info.negotiated) {
          init.negotiated = true;
          if (info.id !== null) init.id = info.id;
        }
        if (info.max_retransmits !== null) init.maxRetransmits = info.max_retransmits;
        if (info.max_packet_life_time_ms !== null) init.maxPacketLifeTime = info.max_packet_life_time_ms;
        this.bindChannel(channel, pc.createDataChannel(info.name, init));
      }
    }
    if (offerer) {
      this.initialTracksAttached = true;
      const sent = new Set<string>();
      for (const track of this.local.tracks) {
        const kind = track.kind as "audio" | "video";
        sent.add(kind);
        pc.addTransceiver(track, {
          direction: serverSends(hello.media[kind]) ? "sendrecv" : "sendonly",
          streams: this.local.streams,
        });
      }
      for (const kind of ["audio", "video"] as const) {
        if (serverSends(hello.media[kind]) && !sent.has(kind)) {
          pc.addTransceiver(kind, { direction: "recvonly" });
        }
      }
      this.wantOffer = true;
      await this.pump();
    }
  }

  private async onDescription(message: DescriptionMessage): Promise<void> {
    const pc = this.requirePeer();
    const description = message.description;
    if (description.type === "answer") {
      if (pc.signalingState !== "have-local-offer" || this.localOffer !== message.negotiation) {
        return; // stale answer
      }
      await pc.setRemoteDescription(description);
      this.localOffer = null;
      await this.flushCandidates();
      await this.pump();
      return;
    }
    // The browser is the polite peer: it rolls back its own offer on collision.
    if (pc.signalingState !== "stable") {
      await pc.setLocalDescription({ type: "rollback" });
      if (this.localOffer !== null) {
        this.localOffer = null;
        this.wantOffer = true;
      }
    }
    await pc.setRemoteDescription(description);
    if (!this.initialTracksAttached) {
      this.initialTracksAttached = true;
      this.attachToOfferedTransceivers(pc);
    }
    await pc.setLocalDescription(await pc.createAnswer());
    const answer = pc.localDescription;
    if (answer === null) throw new RtcError("negotiation_failed");
    this.send({
      type: "description",
      description: { type: answer.type, sdp: answer.sdp },
      negotiation: message.negotiation,
    });
    await this.flushCandidates();
    await this.pump();
  }

  private attachToOfferedTransceivers(pc: RTCPeerConnection): void {
    for (const track of this.local.tracks) {
      const transceiver = pc
        .getTransceivers()
        .find((t) => t.receiver.track.kind === track.kind && t.sender.track === null && t.currentDirection !== "stopped");
      if (transceiver === undefined) {
        pc.addTrack(track, ...this.local.streams);
        continue;
      }
      void transceiver.sender.replaceTrack(track);
      if (this.local.streams.length > 0) transceiver.sender.setStreams(...this.local.streams);
      transceiver.direction = transceiver.direction === "recvonly" ? "sendrecv" : "sendonly";
    }
  }

  private async onCandidate(candidate: RTCIceCandidateInit | null): Promise<void> {
    const pc = this.requirePeer();
    if (pc.remoteDescription === null) {
      this.pendingCandidates.push(candidate);
      return;
    }
    await this.addCandidate(pc, candidate);
  }

  private async flushCandidates(): Promise<void> {
    const pc = this.requirePeer();
    const pending = this.pendingCandidates;
    this.pendingCandidates = [];
    for (const candidate of pending) await this.addCandidate(pc, candidate);
  }

  private async addCandidate(pc: RTCPeerConnection, candidate: RTCIceCandidateInit | null): Promise<void> {
    try {
      if (candidate === null) await pc.addIceCandidate();
      else await pc.addIceCandidate(candidate);
    } catch {
      // Candidates of a rolled-back or replaced description are expected to fail.
    }
  }

  /** Create an offer when one is wanted and the connection is stable. */
  private async pump(): Promise<void> {
    const pc = this.pc;
    if (pc === null || this.finished !== null) return;
    if (pc.signalingState !== "stable" || this.localOffer !== null) return;
    if (!this.wantOffer) {
      this.settle();
      return;
    }
    this.wantOffer = false;
    await pc.setLocalDescription(await pc.createOffer());
    const offer = pc.localDescription;
    if (offer === null) throw new RtcError("negotiation_failed");
    this.negotiationCounter += 1;
    this.localOffer = this.negotiationCounter;
    this.send({
      type: "description",
      description: { type: offer.type, sdp: offer.sdp },
      negotiation: this.localOffer,
    });
  }

  private settle(): void {
    const waiters = this.settledWaiters;
    this.settledWaiters = [];
    for (const waiter of waiters) waiter();
  }

  private renegotiate(): Promise<void> {
    if (this.finished !== null) return Promise.reject(this.finished);
    if (this.hello !== null && !this.hello.capabilities.renegotiation) {
      return Promise.reject(new RtcError("negotiation_failed", "The server engine cannot renegotiate."));
    }
    const settled = new Promise<void>((resolve, reject) => {
      this.settledWaiters.push(() => (this.finished === null ? resolve() : reject(this.finished)));
    });
    this.wantOffer = true;
    this.enqueue(() => this.pump());
    return settled;
  }

  // -------------------------------------------------------------- channels

  private bindChannel(channel: Channel, data: RTCDataChannel): void {
    channel.data = data;
    data.binaryType = "arraybuffer";
    data.bufferedAmountLowThreshold = this.options.sendBufferHighBytes ?? DEFAULT_SEND_BUFFER_HIGH_BYTES;
    const wake = () => {
      for (const waiter of [...channel.waiters]) waiter();
    };
    data.onopen = () => {
      wake();
      this.checkOpen();
    };
    data.onclose = wake;
    data.onbufferedamountlow = wake;
    data.onmessage = (event: MessageEvent) => {
      let message: unknown;
      try {
        message = decodeMessage(channel.info.send_format, event.data);
      } catch (error) {
        this.report(isRtcError(error) ? new RtcError(error.code, error.message, { channel: channel.name }) : new RtcError("invalid_message"));
        return;
      }
      for (const handler of channel.handlers) this.call(() => handler(message), channel.name);
    };
  }

  private channelApi(name: string): RtcChannel<unknown, unknown> {
    const connection = this;
    const lookup = (): Channel => {
      const channel = connection.channels.get(name);
      if (channel === undefined) throw new RtcError("channel_closed", `Channel ${name} is not available.`);
      return channel;
    };
    return {
      name,
      get isOpen() {
        return connection.channels.get(name)?.data?.readyState === "open";
      },
      get bufferedAmount() {
        return connection.channels.get(name)?.data?.bufferedAmount ?? 0;
      },
      get dataChannel() {
        const data = lookup().data;
        if (data === null) throw new RtcError("channel_closed", `Channel ${name} is not open yet.`);
        return data;
      },
      send: (message: unknown) => connection.sendMessage(lookup(), message),
      subscribe: (handler) => {
        const channel = lookup();
        const wrapped = (message: unknown) => handler(message);
        channel.handlers.add(wrapped);
        return () => channel.handlers.delete(wrapped);
      },
    };
  }

  private async sendMessage(channel: Channel, message: unknown): Promise<void> {
    if (this.finished !== null) throw this.finished;
    const data = encodeMessage(channel.info.receive_format, message);
    if (byteLength(data) > channel.info.max_message_bytes) {
      throw new RtcError("message_too_large", `The message exceeds ${channel.info.max_message_bytes} bytes.`, {
        channel: channel.name,
      });
    }
    const high = this.options.sendBufferHighBytes ?? DEFAULT_SEND_BUFFER_HIGH_BYTES;
    for (;;) {
      if (this.finished !== null) throw this.finished;
      const dc = channel.data;
      if (dc !== null && (dc.readyState === "closing" || dc.readyState === "closed")) {
        throw new RtcError("channel_closed", undefined, { channel: channel.name });
      }
      if (dc !== null && dc.readyState === "open" && dc.bufferedAmount <= high) {
        dc.send(data as string);
        return;
      }
      await new Promise<void>((resolve) => {
        const waiter = () => {
          channel.waiters.delete(waiter);
          resolve();
        };
        channel.waiters.add(waiter);
      });
    }
  }

  // ----------------------------------------------------------- lifecycle

  private checkOpen(): void {
    if (this.state !== "connecting" || !this.ready || this.finished !== null) return;
    for (const channel of this.channels.values()) {
      if (channel.data?.readyState !== "open") return;
    }
    this.state = "open";
    if (this.timer !== null) clearTimeout(this.timer);
    this.timer = null;
    this.call(() => this.options.onStateChange?.("open", this.session));
    const resolve = this.resolveConnect;
    this.resolveConnect = null;
    this.rejectConnect = null;
    resolve?.(this.session);
  }

  private report(error: RtcError): void {
    if (this.options.onError === undefined) {
      console.warn(`fastapi-webrtc: ${error.code}: ${error.message}`);
      return;
    }
    this.call(() => this.options.onError?.(error, this.session));
  }

  private call(callback: () => unknown, channel?: string): void {
    try {
      const result = callback();
      if (result instanceof Promise) {
        result.catch((cause: unknown) => this.handlerFailed(cause, channel));
      }
    } catch (cause) {
      this.handlerFailed(cause, channel);
    }
  }

  private handlerFailed(cause: unknown, channel: string | undefined): void {
    const error = new RtcError("handler_failure", "A session callback failed.", { channel, cause });
    if (this.options.onError === undefined) {
      console.error(error, cause);
      return;
    }
    try {
      this.options.onError(error, this.session);
    } catch (nested) {
      console.error(nested);
    }
  }

  private fail(error: RtcError): void {
    this.finish(error, 4000);
  }

  private finish(reason: RtcError, closeCode = 1000): void {
    if (this.finished !== null) return;
    this.finished = reason;
    const previous = this.state;
    this.state = "closed";
    if (this.timer !== null) clearTimeout(this.timer);
    this.timer = null;
    if (this.abortListener !== null) this.options.signal?.removeEventListener("abort", this.abortListener);
    // Close signaling first so the server records the reason, not a transport loss.
    const socket = this.socket;
    if (socket !== null && (socket.readyState === 0 || socket.readyState === 1)) {
      try {
        socket.close(closeCode, reason.code === "closed" ? undefined : reason.code);
      } catch {
        socket.close();
      }
    }
    for (const channel of this.channels.values()) {
      for (const waiter of [...channel.waiters]) waiter();
      try {
        channel.data?.close();
      } catch {
        // already closed
      }
    }
    // Never stop local tracks: they are borrowed from the caller.
    try {
      this.pc?.close();
    } catch {
      // already closed
    }
    this.settle();
    const reject = this.rejectConnect;
    this.resolveConnect = null;
    this.rejectConnect = null;
    reject?.(reason);
    if (previous !== "closed") this.call(() => this.options.onStateChange?.("closed", this.session));
    this.call(() => this.options.onClose?.(reason));
    this.resolveClosed(reason);
  }

  private requirePeer(): RTCPeerConnection {
    if (this.pc === null) throw this.finished ?? new RtcError("closed");
    return this.pc;
  }

  private createSession(): RtcSession<C> {
    const connection = this;
    const channels: Record<string, RtcChannel<unknown, unknown>> = {};
    for (const channel of this.descriptor.channels) channels[channel.name] = this.channelApi(channel.name);
    return {
      get id() {
        return connection.hello?.session_id ?? "";
      },
      name: this.descriptor.name,
      get state() {
        return connection.state;
      },
      channels: channels as SessionChannels<C>,
      get peerConnection() {
        return connection.requirePeer();
      },
      get remoteTracks() {
        return connection.remoteTracks;
      },
      closed: this.closedPromise,
      addTrack: async (track: MediaStreamTrack, ...streams: MediaStream[]) => {
        checkTrack(this.descriptor.media, track);
        const pc = this.requirePeer();
        const reusable = pc
          .getTransceivers()
          .find((t) => t.receiver.track.kind === track.kind && t.sender.track === null && t.currentDirection !== "stopped");
        if (reusable !== undefined) {
          await reusable.sender.replaceTrack(track);
          if (streams.length > 0) reusable.sender.setStreams(...streams);
          reusable.direction = reusable.direction === "recvonly" || reusable.direction === "sendrecv" ? "sendrecv" : "sendonly";
        } else {
          pc.addTrack(track, ...streams);
        }
        await this.renegotiate();
      },
      removeTrack: async (track: MediaStreamTrack) => {
        const pc = this.requirePeer();
        const sender = pc.getSenders().find((s) => s.track === track);
        if (sender === undefined) return;
        pc.removeTrack(sender);
        await this.renegotiate();
      },
      stats: () => this.requirePeer().getStats(),
      close: async () => {
        this.finish(new RtcError("closed"));
        await this.closedPromise;
      },
    };
  }
}
